update public.techniques
set nombre_en = 'Compute a long mean with a provisional mean',
    descripcion_en = 'When the data are large but similar, assume a mean and add up only the differences.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Adding big numbers is slow and error-prone. With the data $61, 64, 58, 67, 60$, all close to $60$, there is a shortcut.","Pick a provisional mean $m$ close to the data (here, $m = 60$) and write down the difference of each data point with $m$: $+1, +4, -2, +7, 0$.","Add those differences: $1 + 4 - 2 + 7 + 0 = 10$. Divide by the number of data points: $10 / 5 = 2$.","The real mean is the provisional one plus that average of differences: $\\bar{x} = 60 + 2 = 62$.","Check: $61 + 64 + 58 + 67 + 60 = 310$ and $310 / 5 = 62$. If the differences cancel out (they add up to $0$), the provisional mean was exactly the mean."]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"estadistica.desvios","despuesDePaso":1,"titulo":"Differences from the provisional mean","datos":[61,64,58,67,60],"centro":60,"etiquetaCentro":"Provisional mean"}]$leccion_en$::jsonb
    )
where slug = 'estadistica-media-desde-una-media-provisoria';

update public.techniques
set nombre_en = 'Find the median by position',
    descripcion_en = 'Sort first and work out which position the middle data point is in, without counting one by one.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Always sort the data from smallest to largest before looking for the median: without that step, any result is wrong.","With odd $n$, the median is at position $\\dfrac{n+1}{2}$. Data $9, 3, 7, 5, 11, 1, 8$ → sorted $1, 3, 5, 7, 8, 9, 11$; with $n = 7$, the position is $\\dfrac{7+1}{2} = 4$ and the median is $7$.","With even $n$ there are two middle values (positions $\\dfrac{n}{2}$ and $\\dfrac{n}{2}+1$): the median is their average. Data $12, 4, 9, 7$ → sorted $4, 7, 9, 12$; middle ones $7$ and $9$; median $= \\dfrac{7+9}{2} = 8$.","Extreme values do not move it: if in $4, 7, 9, 12$ the $12$ were $120$, the median would still be $8$."]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"estadistica.ordenar","despuesDePaso":1,"titulo":"With odd n, the median is the middle data point","datos":[9,3,7,5,11,1,8],"resaltar":"mediana"},{"tipo":"estadistica.ordenar","despuesDePaso":2,"titulo":"With even n, the median is the average of the two middle ones","datos":[12,4,9,7],"resaltar":"mediana"},{"tipo":"estadistica.ordenar","despuesDePaso":3,"titulo":"Even if the 12 were 120, the median does not move","datos":[120,4,9,7],"resaltar":"mediana"}]$leccion_en$::jsonb
    )
where slug = 'estadistica-mediana-por-posicion';

update public.techniques
set nombre_en = 'Quartiles and interquartile range by halves',
    descripcion_en = 'Split the sorted data into two halves and take the median of each one.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Sort and split the data at the median into two halves: the lower and the upper one. If $n$ is odd, the median does not go in either half.","$Q_1$ is the median of the lower half and $Q_3$ that of the upper half. The interquartile range is $IQR = Q_3 - Q_1$.","Example with $n = 8$: $2, 4, 4, 5 \\mid 7, 8, 9, 12$. Lower half $2, 4, 4, 5$ → $Q_1 = \\dfrac{4+4}{2} = 4$. Upper half $7, 8, 9, 12$ → $Q_3 = \\dfrac{8+9}{2} = 8.5$. So $IQR = 8.5 - 4 = 4.5$.","Example with $n = 7$: $1, 3, 4 \\mid 6 \\mid 8, 9, 11$. The $6$ (the median) is left out of both halves. $Q_1 = 3$, $Q_3 = 9$ and $IQR = 6$.","This is the method the Statistics practice uses and it always states it in the problem: there are other quartile methods that give slightly different values."]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"estadistica.ordenar","despuesDePaso":2,"titulo":"Eight data points: two halves of four","datos":[2,4,4,5,7,8,9,12],"resaltar":"cuartiles"},{"tipo":"estadistica.ordenar","despuesDePaso":3,"titulo":"Seven data points: the median is left out of the halves","datos":[1,3,4,6,8,9,11],"resaltar":"cuartiles"}]$leccion_en$::jsonb
    )
where slug = 'estadistica-cuartiles-por-mitades';

update public.techniques
set nombre_en = 'Combinatorics without huge factorials',
    descripcion_en = 'Cancel instead of computing full factorials and use the symmetry of combinations.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Do not compute full factorials: cancel. $C(n, r) = \\dfrac{n!}{r!\\,(n-r)!}$ is solved by multiplying $r$ factors going down from $n$ and dividing by $r!$.","$C(10, 3) = \\dfrac{10 \\cdot 9 \\cdot 8}{3 \\cdot 2 \\cdot 1} = \\dfrac{720}{6} = 120$.","Use the symmetry $C(n, r) = C(n, n-r)$ to shrink the calculation: $C(10, 8) = C(10, 2) = \\dfrac{10 \\cdot 9}{2 \\cdot 1} = 45$.","Permutations (order matters): $P(n, r) = n \\cdot (n-1) \\cdots (n-r+1)$, without dividing. $P(8, 3) = 8 \\cdot 7 \\cdot 6 = 336$.","Useful relation: $C(n, r) = \\dfrac{P(n, r)}{r!}$. For example, $C(8, 3) = \\dfrac{336}{6} = 56$.","To choose between the two, ask yourself: if I change the order of the chosen ones, is it a different result? Yes → permutation; no → combination."]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":1,"titulo":"Combinations without huge factorials","cuadros":[{"texto":"Order does not matter: the permutations are divided by $3!$."},{"formula":"C(10, 3) = \\dfrac{10 \\cdot 9 \\cdot 8}{3 \\cdot 2 \\cdot 1} = \\dfrac{720}{6}","resaltar":"$= 120$"}]},{"tipo":"cuadros","despuesDePaso":2,"titulo":"Symmetry of combinations","cuadros":[{"texto":"By symmetry, $C(10, 8) = C(10, 2)$: it is better to compute with the smaller number."},{"formula":"C(10, 8) = C(10, 2) = \\dfrac{10 \\cdot 9}{2 \\cdot 1}","resaltar":"$= 45$"}]},{"tipo":"cuadros","despuesDePaso":3,"titulo":"Permutations: order matters","cuadros":[{"texto":"Order matters: $3$ factors are multiplied going down from $8$, without dividing."},{"formula":"P(8, 3) = 8 \\cdot 7 \\cdot 6","resaltar":"$= 336$"}]},{"tipo":"cuadros","despuesDePaso":4,"titulo":"From permutations to combinations","cuadros":[{"texto":"Order does not matter: the permutations are divided by $3!$."},{"formula":"C(8, 3) = \\dfrac{8 \\cdot 7 \\cdot 6}{3 \\cdot 2 \\cdot 1} = \\dfrac{336}{6}","resaltar":"$= 56$"}]}]$leccion_en$::jsonb
    )
where slug = 'estadistica-combinatoria-sin-factoriales-enormes';

update public.techniques
set nombre_en = 'Variance from the deviations',
    descripcion_en = 'With a whole-number mean, the deviations are whole numbers and the variance comes out without messy decimals.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["For the population variance look for the mean first: if it is a whole number, all the deviations are whole numbers and the calculation stays clean.","Data $2, 4, 4, 4, 5, 5, 7, 9$: the sum is $40$, there are $n = 8$ data points and the mean is $\\bar{x} = 5$.","Deviations $x - \\bar{x}$: $-3, -1, -1, -1, 0, 0, 2, 4$. Squared: $9, 1, 1, 1, 0, 0, 4, 16$.","Add up the squares: $9 + 1 + 1 + 1 + 0 + 0 + 4 + 16 = 32$. Population variance: $\\sigma^2 = \\dfrac{32}{8} = 4$.","The standard deviation is the square root of the variance: $\\sigma = \\sqrt{4} = 2$.","For the sample variance you divide by $n - 1$ instead of $n$: $s^2 = \\dfrac{32}{7} \\approx 4.57$. Always check which of the two is asked for."]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"estadistica.desvios","despuesDePaso":2,"titulo":"Deviations from the mean and their squares","datos":[2,4,4,4,5,5,7,9],"centro":5,"etiquetaCentro":"Mean","mostrarCuadrados":true}]$leccion_en$::jsonb
    )
where slug = 'estadistica-varianza-con-desvios';

update public.techniques
set nombre_en = 'Class 1: Data and types of variable',
    descripcion_en = 'What a data point is, population and sample, and how to classify any variable.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Statistics works with data: observations of a characteristic in a group. The population is the whole group you are interested in; the sample is the part you actually measure. A number computed on the population is called a parameter; computed on the sample, a statistic.","Each characteristic that is observed is a variable. There are two families: qualitative (categories, like eye color or clothing size) and quantitative (numbers that make sense, like age or number of siblings).","Nominal qualitative: the categories have no natural order (eye color). Ordinal qualitative: the categories do have an order (size S, M, L).","Discrete quantitative: it takes separate values and is counted (number of siblings: $0, 1, 2, \\dots$). Continuous quantitative: it can take any value in an interval and is measured (height: $1.62$ m, $1.625$ m, $\\dots$).","Worked example: in a survey of 30 people the following are recorded: (a) neighborhood where they live, (b) satisfaction: low, medium or high, (c) number of pets and (d) minutes of commute to work. Classification: (a) nominal qualitative, (b) ordinal qualitative, (c) discrete quantitative and (d) continuous quantitative.","Why it matters: the type of variable decides what can be computed. The mean of the number of pets makes sense, but the \"average\" of neighborhoods does not; for a nominal variable the mode is used."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"What type of variable is \"number of goals in a match\"?","opciones":["Discrete quantitative","Continuous quantitative","Nominal qualitative","Ordinal qualitative"],"respuesta":"Discrete quantitative","explicacion":"It is counted with separate values ($0, 1, 2, \\dots$), so it is discrete quantitative."},{"pregunta":"Level of education (primary, secondary, university) is a variable that is:","opciones":["Nominal qualitative","Continuous quantitative","Ordinal qualitative","Discrete quantitative"],"respuesta":"Ordinal qualitative","explicacion":"They are categories (qualitative) and they have a natural order, so it is ordinal."},{"pregunta":"The height of 40 students chosen from a school of 900 is measured. The 900 students are the ___ and the 40 are the ___.","opciones":["sample; population","variable; parameter","population; sample","parameter; statistic"],"respuesta":"population; sample","explicacion":"The population is the whole group of interest (900); the sample is the part that is measured (40)."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":4,"titulo":"Classify the four variables of the survey","cuadros":[{"texto":"A survey of 30 people records four variables."},{"texto":"(a) Neighborhood where they live: categories with no natural order.","resaltar":"Cualitativa nominal"},{"texto":"(b) Satisfaction (low, medium or high): categories that do have an order.","resaltar":"Cualitativa ordinal"},{"texto":"(c) Number of pets: separate values that are counted.","resaltar":"Cuantitativa discreta"},{"texto":"(d) Minutes of commute to work: it can be any value in an interval and is measured.","resaltar":"Cuantitativa continua"}]}]$leccion_en$::jsonb
    )
where slug = 'estadistica-clase-1-datos-y-tipos-de-variable';

update public.techniques
set nombre_en = 'Class 2: Mean, median and mode',
    descripcion_en = 'The three measures of central tendency, when to use each one and why extremes affect them differently.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Central tendency sums up a set of data with a single \"typical\" value. The three classic measures are the mean, the median and the mode.","Mean: $\\bar{x} = \\dfrac{\\sum x_i}{n}$, the sum of the data divided by their number. It is the balance point of the data.","Median: the middle value of the sorted data (the average of the two middle ones if $n$ is even). Half of the data is below and half above.","Mode: the value that repeats the most. It may not exist or there may be more than one.","Worked example: salaries (in thousands) of 5 employees: $3, 5, 5, 7, 50$. Mean: $\\dfrac{3+5+5+7+50}{5} = \\dfrac{70}{5} = 14$. Median: they are already sorted and position $3$ is $5$. Mode: $5$ (it appears twice).","Reading: the $50$ (an extreme value) drags the mean up to $14$, a value that represents almost nobody. The median ($5$) resists extremes. With very skewed data or with outliers, the median is better.","Frequency table: if the value $x_i$ appears $f_i$ times, the mean is $\\bar{x} = \\dfrac{\\sum x_i f_i}{\\sum f_i}$. With values $1, 2, 3$ and frequencies $2, 5, 3$: $\\dfrac{1 \\cdot 2 + 2 \\cdot 5 + 3 \\cdot 3}{10} = \\dfrac{21}{10} = 2.1$.","Missing data point: if you know the mean, you know the total sum, because $\\text{total sum} = \\bar{x} \\cdot n$. Example: the mean of $5$ data points is $8$ and the other four data points are $4, 9, 11, 7$. Total sum: $8 \\cdot 5 = 40$. Sum of the known data: $4 + 9 + 11 + 7 = 31$. The missing data point is the difference: $40 - 31 = 9$.","Another way to see it: the deviations from the mean always add up to $0$. Those of the known data are $-4, +1, +3, -1$ and add up to $-1$, so the missing data point has to be $+1$: $8 + 1 = 9$. Check: $\\dfrac{4+9+11+7+9}{5} = \\dfrac{40}{5} = 8$."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"Data $2, 4, 4, 6, 9$. What is the mean?","opciones":["$4$","$5$","$6$","$4.5$"],"respuesta":"$5$","explicacion":"$2 + 4 + 4 + 6 + 9 = 25$ and $25 / 5 = 5$."},{"pregunta":"With the data $1, 2, 3, 4, 100$, which measure best describes a typical data point?","opciones":["The mean ($22$)","The median ($3$)","The range ($99$)","The mean, because it uses all the data"],"respuesta":"The median ($3$)","explicacion":"The $100$ drags the mean up to $22$, while the median ($3$) does not move because of the extreme."},{"pregunta":"Data $8, 3, 5, 10$. What is the median?","opciones":["$5$","$8$","$6.5$","$6$"],"respuesta":"$6.5$","explicacion":"Sorted: $3, 5, 8, 10$. With even $n$, the median is the average of the middle ones: $\\dfrac{5+8}{2} = 6.5$."},{"pregunta":"The mean of $4$ data points is $10$. Three of the data points are $8, 12$ and $9$. What is the fourth data point?","opciones":["$9$","$10$","$11$","$12$"],"respuesta":"$11$","explicacion":"The total sum is $10 \\cdot 4 = 40$ and the three known data points add up to $8 + 12 + 9 = 29$, so $40 - 29 = 11$ is missing. The $10$ is the mean, not the missing data point."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"estadistica.ordenar","despuesDePaso":4,"titulo":"The median of the salaries","datos":[3,5,5,7,50],"resaltar":"mediana"},{"tipo":"estadistica.frecuencias","despuesDePaso":4,"titulo":"The mode and the mean of the salaries","datos":[3,5,5,7,50],"mostrarMedia":true},{"tipo":"estadistica.desvios","despuesDePaso":5,"titulo":"The mean is the balance point: the deviations add up to 0","datos":[3,5,5,7,50],"centro":14,"etiquetaCentro":"Mean"},{"tipo":"estadistica.frecuencias","despuesDePaso":6,"titulo":"The values 1, 2 and 3 with frequencies 2, 5 and 3","datos":[1,1,2,2,2,2,2,3,3,3],"mostrarMedia":true},{"tipo":"cuadros","despuesDePaso":7,"titulo":"Finding the missing data point from the mean","cuadros":[{"texto":"The mean of $5$ data points is $8$; four data points are $4, 9, 11, 7$. The total sum comes from the mean."},{"formula":"8 \\cdot 5","resaltar":"$= 40$"},{"texto":"The known data add up to $4 + 9 + 11 + 7 = 31$."},{"formula":"40 - 31","resaltar":"$= 9$ (el dato que falta)"}]},{"tipo":"estadistica.desvios","despuesDePaso":8,"titulo":"With the missing data point (9) included, the deviations add up to 0","datos":[4,9,11,7,9],"centro":8,"etiquetaCentro":"Mean"}]$leccion_en$::jsonb
    )
where slug = 'estadistica-clase-2-tendencia-central';

update public.techniques
set nombre_en = 'Class 3: Dispersion, variance and standard deviation',
    descripcion_en = 'Range, interquartile range, population and sample variance, and how they change when the data are transformed.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Two groups can have the same mean and be very different: $4, 5, 6$ and $0, 5, 10$ have mean $5$. Dispersion measures how far the data move away from their center.","Range: $\\text{max} - \\text{min}$. It is simple, but it depends on only two data points. Interquartile range: $IQR = Q_3 - Q_1$ (quartiles by the halves method); it ignores the extremes.","Population variance: $\\sigma^2 = \\dfrac{\\sum (x_i - \\mu)^2}{N}$. Sample variance: $s^2 = \\dfrac{\\sum (x_i - \\bar{x})^2}{n-1}$. The standard deviation is the root ($\\sigma$ or $s$) and stays in the same units as the data.","Why $n - 1$ in the sample one: since $\\bar{x}$ is computed from the same data, the deviations come out a bit smaller than from the real mean; dividing by $n - 1$ compensates for that bias. Use $n$ only if you have the whole population.","Worked example with $4, 8, 6, 5, 12$: the mean is $\\dfrac{35}{5} = 7$. Deviations: $-3, 1, -1, -2, 5$. Squares: $9, 1, 1, 4, 25$, with sum $40$.","If it is the whole population: $\\sigma^2 = \\dfrac{40}{5} = 8$ and $\\sigma = \\sqrt{8} \\approx 2.83$. If it is a sample: $s^2 = \\dfrac{40}{4} = 10$ and $s = \\sqrt{10} \\approx 3.16$.","Effect of transforming the data: adding a constant moves the mean but does not change any measure of dispersion; multiplying by $k$ multiplies the standard deviation by $|k|$ and the variance by $k^2$. With the example data multiplied by $2$ ($8, 16, 12, 10, 24$), the population variance goes from $8$ to $32$ and the population standard deviation from $\\sqrt{8}$ to $2\\sqrt{8}$."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"Data $3, 5, 7, 9$ (the whole population). What is the population variance?","opciones":["$20$","$6.67$","$5$","$2.24$"],"respuesta":"$5$","explicacion":"The mean is $6$; the squared deviations are $9, 1, 1, 9$ (sum $20$). $\\sigma^2 = \\dfrac{20}{4} = 5$. The $6.67$ would be the sample one and the $2.24$ is the standard deviation."},{"pregunta":"With those same data $3, 5, 7, 9$ but as a SAMPLE, what is the sample variance?","opciones":["$5$","$\\dfrac{20}{3} \\approx 6.67$","$20$","$4$"],"respuesta":"$\\dfrac{20}{3} \\approx 6.67$","explicacion":"In the sample one you divide by $n - 1 = 3$: $s^2 = \\dfrac{20}{3} \\approx 6.67$."},{"pregunta":"If you add 10 to all the data, what happens to the standard deviation?","opciones":["It goes up by 10","It does not change","It is multiplied by 10","It goes up by 100"],"respuesta":"It does not change","explicacion":"Adding a constant shifts all the data equally: the mean goes up by 10 but the distances between data (and therefore the standard deviation) do not change."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"estadistica.desvios","despuesDePaso":0,"titulo":"Data 4, 5 and 6: close to the mean","datos":[4,5,6],"centro":5,"etiquetaCentro":"Mean","mostrarCuadrados":true},{"tipo":"estadistica.desvios","despuesDePaso":0,"titulo":"Data 0, 5 and 10: far from the mean","datos":[0,5,10],"centro":5,"etiquetaCentro":"Mean","mostrarCuadrados":true},{"tipo":"estadistica.desvios","despuesDePaso":4,"titulo":"Deviations and squares of the worked example","datos":[4,8,6,5,12],"centro":7,"etiquetaCentro":"Mean","mostrarCuadrados":true},{"tipo":"estadistica.desvios","despuesDePaso":6,"titulo":"The data multiplied by 2","datos":[8,16,12,10,24],"centro":14,"etiquetaCentro":"Mean","mostrarCuadrados":true}]$leccion_en$::jsonb
    )
where slug = 'estadistica-clase-3-dispersion';

update public.techniques
set nombre_en = 'Class 4: Simple, independent and conditional probability',
    descripcion_en = 'From counting favorable cases to independent and dependent events and conditional probability with tables.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["With equally likely cases, $P(A) = \\dfrac{\\text{favorable cases}}{\\text{possible cases}}$. It is always between $0$ and $1$.","Example: a bag with 3 red balls, 5 blue and 2 green (10 in total). $P(\\text{red}) = \\dfrac{3}{10}$.","Complement: $P(\\text{not } A) = 1 - P(A)$. So $P(\\text{not red}) = 1 - \\dfrac{3}{10} = \\dfrac{7}{10}$ (which is also $\\dfrac{5+2}{10}$).","Independent events (with replacement): $P(A \\text{ and } B) = P(A) \\cdot P(B)$. Red and then blue putting the ball back: $\\dfrac{3}{10} \\cdot \\dfrac{5}{10} = \\dfrac{15}{100} = \\dfrac{3}{20}$.","Without replacement, the second event depends on the first: $9$ balls are left. Red and then blue: $\\dfrac{3}{10} \\cdot \\dfrac{5}{9} = \\dfrac{15}{90} = \\dfrac{1}{6}$.","Conditional probability: $P(B \\mid A) = \\dfrac{P(A \\text{ and } B)}{P(A)}$; in practice, \"of the cases where $A$ happened, in how many does $B$ happen?\". Example with a table: of 40 students, 18 studied and passed, 6 studied and failed, 4 did not study and passed, 12 did not study and failed.","$P(\\text{passed} \\mid \\text{studied}) = \\dfrac{18}{18+6} = \\dfrac{18}{24} = \\dfrac{3}{4}$. It is not the same as $P(\\text{studied} \\mid \\text{passed}) = \\dfrac{18}{18+4} = \\dfrac{18}{22} = \\dfrac{9}{11}$: reversing the condition changes the answer."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"A fair 6-sided die. What is the probability of rolling a prime number (2, 3 or 5)?","opciones":["$\\dfrac{1}{3}$","$\\dfrac{1}{2}$","$\\dfrac{2}{3}$","$\\dfrac{1}{6}$"],"respuesta":"$\\dfrac{1}{2}$","explicacion":"There are $3$ favorable cases out of $6$ possible: $\\dfrac{3}{6} = \\dfrac{1}{2}$."},{"pregunta":"A bag has 4 red balls and 6 blue ones. 2 balls are drawn, one after the other and without putting them back. What is the probability that both are red?","opciones":["$\\dfrac{4}{25}$","$\\dfrac{3}{10}$","$\\dfrac{2}{15}$","$\\dfrac{1}{5}$"],"respuesta":"$\\dfrac{2}{15}$","explicacion":"Without replacement: $\\dfrac{4}{10} \\cdot \\dfrac{3}{9} = \\dfrac{12}{90} = \\dfrac{2}{15}$. The $\\dfrac{4}{25}$ would be the result with replacement ($\\dfrac{4}{10} \\cdot \\dfrac{4}{10}$)."},{"pregunta":"Of 50 customers, 20 used a coupon and, of those, 15 bought. What is P(bought | used coupon)?","opciones":["$\\dfrac{3}{10}$","$\\dfrac{2}{5}$","$\\dfrac{1}{4}$","$\\dfrac{3}{4}$"],"respuesta":"$\\dfrac{3}{4}$","explicacion":"You look only at those who used a coupon: $\\dfrac{15}{20} = \\dfrac{3}{4}$. The $\\dfrac{3}{10}$ ($\\dfrac{15}{50}$) divides by all the customers, not by those who used a coupon."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"estadistica.arbol","despuesDePaso":3,"titulo":"Two balls putting back the first: the events are independent","raiz":"Bag: 3 red, 5 blue and 2 green","ramas":[{"etiqueta":"1st red","probabilidad":0.3,"hijos":[{"etiqueta":"2nd blue","probabilidad":0.5},{"etiqueta":"2nd not blue","probabilidad":0.5}]},{"etiqueta":"1st not red","probabilidad":0.7,"hijos":[{"etiqueta":"2nd blue","probabilidad":0.5},{"etiqueta":"2nd not blue","probabilidad":0.5}]}]},{"tipo":"estadistica.arbol","despuesDePaso":6,"titulo":"The 40 students: each branch is a conditional probability","raiz":"40 students","ramas":[{"etiqueta":"Studied","probabilidad":0.6,"hijos":[{"etiqueta":"Passed","probabilidad":0.75},{"etiqueta":"Failed","probabilidad":0.25}]},{"etiqueta":"Did not study","probabilidad":0.4,"hijos":[{"etiqueta":"Passed","probabilidad":0.25},{"etiqueta":"Failed","probabilidad":0.75}]}]}]$leccion_en$::jsonb
    )
where slug = 'estadistica-clase-4-probabilidad';

update public.techniques
set nombre_en = 'Class 5: Combinatorics — counting without listing',
    descripcion_en = 'The multiplication principle, factorial, permutations and combinations, and their use in probability.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Combinatorics is counting without listing. Multiplication principle: if a process has steps with $a$, $b$, $c$, $\\dots$ options, in total there are $a \\cdot b \\cdot c \\cdots$ ways. With $3$ shirts and $4$ pairs of pants there are $3 \\cdot 4 = 12$ outfits.","Factorial: $n! = n \\cdot (n-1) \\cdots 2 \\cdot 1$, with $0! = 1$. It is the number of ways to order $n$ different objects: $5! = 120$ people in a line can be ordered in $120$ ways.","Permutations: choosing $r$ out of $n$ when ORDER matters, $P(n, r) = \\dfrac{n!}{(n-r)!}$. A podium (1st, 2nd and 3rd) among $8$ runners: $P(8, 3) = 8 \\cdot 7 \\cdot 6 = 336$.","Combinations: choosing $r$ out of $n$ when order does NOT matter, $C(n, r) = \\dfrac{n!}{r!\\,(n-r)!} = \\dfrac{P(n, r)}{r!}$. A committee of $3$ people among $8$: $C(8, 3) = \\dfrac{336}{3!} = \\dfrac{336}{6} = 56$.","How to choose: change the order of the same chosen ones and ask yourself whether it is a different result. In a podium it is (permutation); in a committee it is not (combination).","Combinatorics and probability: a bag with $4$ red balls and $6$ blue ones, $2$ are drawn at once. Possible cases: $C(10, 2) = 45$. Cases with both red: $C(4, 2) = 6$. So $P = \\dfrac{6}{45} = \\dfrac{2}{15}$, the same as computing it in a line without replacement: $\\dfrac{4}{10} \\cdot \\dfrac{3}{9}$.","One red and one blue: there are $4 \\cdot 6 = 24$ favorable pairs (any red with any blue), so $P = \\dfrac{24}{45} = \\dfrac{8}{15}$."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"In how many ways can 4 different books be arranged on a shelf?","opciones":["$16$","$12$","$24$","$4$"],"respuesta":"$24$","explicacion":"They are the ways to order $4$ different objects: $4! = 4 \\cdot 3 \\cdot 2 \\cdot 1 = 24$."},{"pregunta":"A club chooses a president and a treasurer (different positions) among 6 members. In how many ways can it do so?","opciones":["$15$","$30$","$12$","$36$"],"respuesta":"$30$","explicacion":"The positions are different, so order matters: $P(6, 2) = 6 \\cdot 5 = 30$. The $15$ would be $C(6, 2)$, if order did not matter."},{"pregunta":"3 different desserts are chosen from 7 (order does not matter). How many selections are there?","opciones":["$210$","$21$","$343$","$35$"],"respuesta":"$35$","explicacion":"$C(7, 3) = \\dfrac{7 \\cdot 6 \\cdot 5}{3 \\cdot 2 \\cdot 1} = \\dfrac{210}{6} = 35$. The $210$ is $P(7, 3)$, which also counts the order."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"cuadros","despuesDePaso":0,"titulo":"Multiplication principle","cuadros":[{"texto":"With $3$ shirts and $4$ pairs of pants, each shirt is combined with each pair of pants."},{"formula":"3 \\cdot 4","resaltar":"$= 12$ conjuntos"}]},{"tipo":"cuadros","despuesDePaso":1,"titulo":"Factorial","cuadros":[{"texto":"They are the ways to order $5$ different objects."},{"formula":"5! = 5 \\cdot 4 \\cdot 3 \\cdot 2 \\cdot 1","resaltar":"$= 120$"}]},{"tipo":"cuadros","despuesDePaso":2,"titulo":"A podium among 8 runners","cuadros":[{"texto":"Order matters: $3$ factors are multiplied going down from $8$, without dividing."},{"formula":"P(8, 3) = 8 \\cdot 7 \\cdot 6","resaltar":"$= 336$"}]},{"tipo":"cuadros","despuesDePaso":3,"titulo":"A committee of 3 among 8 people","cuadros":[{"texto":"Order does not matter: the permutations are divided by $3!$."},{"formula":"C(8, 3) = \\dfrac{8 \\cdot 7 \\cdot 6}{3 \\cdot 2 \\cdot 1} = \\dfrac{336}{6}","resaltar":"$= 56$"}]},{"tipo":"cuadros","despuesDePaso":5,"titulo":"Both balls are red","cuadros":[{"texto":"Possible cases when drawing $2$ balls out of $10$: $C(10, 2) = 45$."},{"texto":"Cases with both red: $C(4, 2) = 6$."},{"formula":"P = \\dfrac{6}{45}","resaltar":"$= \\dfrac{2}{15}$"}]},{"tipo":"cuadros","despuesDePaso":6,"titulo":"One red ball and one blue ball","cuadros":[{"texto":"Each red can be paired with each blue: $4 \\cdot 6 = 24$ favorable pairs."},{"formula":"P = \\dfrac{24}{45}","resaltar":"$= \\dfrac{8}{15}$"}]}]$leccion_en$::jsonb
    )
where slug = 'estadistica-clase-5-combinatoria';

update public.techniques
set nombre_en = 'Class 6: z-score, empirical rule and percentiles',
    descripcion_en = 'Measure how many standard deviations a data point is away, compare different scales and locate a data point within the set.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["z-score: how many standard deviations a data point is away from the mean, $z = \\dfrac{x - \\mu}{\\sigma}$. Positive: above the mean; negative: below; $0$: exactly at the mean.","Example: in a test $\\mu = 70$ and $\\sigma = 8$. Someone scores $86$: $z = \\dfrac{86 - 70}{8} = 2$, two standard deviations above. Someone scores $62$: $z = \\dfrac{62 - 70}{8} = -1$.","Inverse: $x = \\mu + z\\sigma$. What score corresponds to $z = 1.5$? $x = 70 + 1.5 \\cdot 8 = 82$.","Comparing different things: in Math ($\\mu = 70$, $\\sigma = 8$) someone scored $78$, with $z = 1$; in Language ($\\mu = 75$, $\\sigma = 6$) they scored $84$, with $z = 1.5$. Since the $z$ values are on the same scale, you can see they did relatively better in Language.","Empirical rule (normal distribution): approximately 68 % of the data is within $1\\sigma$ of the mean, 95 % within $2\\sigma$ and 99.7 % within $3\\sigma$. With $\\mu = 100$ and $\\sigma = 15$: between $85$ and $115$ is 68 %; between $70$ and $130$, 95 %.","The tails are symmetric: if 95 % is between $70$ and $130$, 5 % is left outside, half on each side; above $130$ there is approximately 2.5 %.","Percentiles (nearest-rank method): percentile $P$ is the data point at position $\\lceil P \\cdot N / 100 \\rceil$ of the sorted set. With $N = 10$ data points $12, 15, 18, 21, 24, 27, 30, 33, 36, 39$: percentile $70$ is at position $\\lceil 7 \\rceil = 7$, that is $30$; percentile $25$ is at $\\lceil 2.5 \\rceil = 3$, that is $18$.","Percentile rank (the way back): given a value $x$, what percentage of the data is less than or equal to $x$? You count how many data points are less than or equal to $x$ and divide by $N$: $\\dfrac{\\text{data} \\le x}{N} \\cdot 100$. With the same $N = 10$ data points and $x = 33$: there are $8$ data points less than or equal ($12, 15, 18, 21, 24, 27, 30, 33$), so $\\dfrac{8}{10} \\cdot 100 = 80$ %.","Check with the previous method: percentile $80$ is at position $\\lceil 80 \\cdot 10 / 100 \\rceil = 8$, that is $33$. One way goes from the percentage to the data point and the other from the data point to the percentage. Careful: you count the data points, not the value: $33$ is not the $33$ %."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"With $\\mu = 50$ and $\\sigma = 5$, what $z$ score does $x = 60$ have?","opciones":["$10$","$0.2$","$-2$","$2$"],"respuesta":"$2$","explicacion":"$z = \\dfrac{60 - 50}{5} = 2$: the data point is two standard deviations above the mean."},{"pregunta":"In a normal variable with $\\mu = 100$ and $\\sigma = 15$, what approximate percentage of the data is between $70$ and $130$?","opciones":["68 %","95 %","99.7 %","50 %"],"respuesta":"95 %","explicacion":"$70 = \\mu - 2\\sigma$ and $130 = \\mu + 2\\sigma$, and at $\\pm 2\\sigma$ there is approximately 95 %."},{"pregunta":"With N = 20 sorted data points, at what position is the 90th percentile according to the nearest-rank method?","opciones":["Position 20","Position 19","Position 18","Position 9"],"respuesta":"Position 18","explicacion":"The position is $\\lceil 90 \\cdot 20 / 100 \\rceil = \\lceil 18 \\rceil = 18$."},{"pregunta":"In a set of $N = 20$ data points, $15$ data points are less than or equal to $62$. What percentage of the data is less than or equal to $62$?","opciones":["15 %","25 %","62 %","75 %"],"respuesta":"75 %","explicacion":"You divide the number of data points by the total: $\\dfrac{15}{20} \\cdot 100 = 75$ %. The $25$ % is what is left above, and the $62$ is the value, not a percentage."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"estadistica.desvios","despuesDePaso":1,"titulo":"z-score of the scores 86 and 62","datos":[86,62],"centro":70,"etiquetaCentro":"Mean","sigma":8},{"tipo":"estadistica.desvios","despuesDePaso":3,"titulo":"Math: the z-score of a 78","datos":[78],"centro":70,"etiquetaCentro":"Mean","sigma":8},{"tipo":"estadistica.desvios","despuesDePaso":3,"titulo":"Language: the z-score of an 84","datos":[84],"centro":75,"etiquetaCentro":"Mean","sigma":6},{"tipo":"estadistica.normal","despuesDePaso":4,"titulo":"Empirical rule with mean 100 and standard deviation 15","media":100,"sigma":15},{"tipo":"estadistica.ordenar","despuesDePaso":6,"titulo":"Percentile 70 with N = 10 data points","datos":[12,15,18,21,24,27,30,33,36,39],"resaltar":"posicion","posicion":7,"etiquetaPosicion":"Percentile 70"},{"tipo":"estadistica.ordenar","despuesDePaso":6,"titulo":"Percentile 25 with N = 10 data points","datos":[12,15,18,21,24,27,30,33,36,39],"resaltar":"posicion","posicion":3,"etiquetaPosicion":"Percentile 25"},{"tipo":"estadistica.ordenar","despuesDePaso":7,"titulo":"Percentile rank of 33 with N = 10 data points","datos":[12,15,18,21,24,27,30,33,36,39],"resaltar":"posicion","posicion":8,"etiquetaPosicion":"33 is the last of 8 data points less than or equal"},{"tipo":"cuadros","despuesDePaso":7,"titulo":"From a value to the percentage of data","cuadros":[{"texto":"With $N = 10$ data points, those less than or equal to $33$ are $8$."},{"formula":"\\dfrac{8}{10} \\cdot 100","resaltar":"$= 80$ %"}]}]$leccion_en$::jsonb
    )
where slug = 'estadistica-clase-6-normal-z-y-percentiles';

update public.techniques
set nombre_en = 'Class 7: Correlation and simple linear regression',
    descripcion_en = 'Measuring the relationship between two variables, fitting a least squares line and not drawing too many conclusions.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["Sometimes two variables are measured in the same people (hours of study and grade). Correlation measures how well a line describes the relationship between the two. The Pearson coefficient $r$ goes from $-1$ to $1$.","Sign: $r > 0$, when one goes up the other tends to go up; $r < 0$, when one goes up the other tends to go down; $r$ near $0$, there is no LINEAR relationship. Values near $\\pm 1$ indicate a strong linear relationship.","Formula: $r = \\dfrac{S_{xy}}{\\sqrt{S_{xx}\\,S_{yy}}}$, with $S_{xy} = \\sum (x_i - \\bar{x})(y_i - \\bar{y})$, $S_{xx} = \\sum (x_i - \\bar{x})^2$ and $S_{yy} = \\sum (y_i - \\bar{y})^2$.","Worked example: $x = 1, 2, 3, 4, 5$ and $y = 1, 3, 2, 5, 4$. Means: $\\bar{x} = 3$ and $\\bar{y} = 3$. Deviations of $x$: $-2, -1, 0, 1, 2$; of $y$: $-2, 0, -1, 2, 1$.","Products: $4, 0, 0, 2, 2$, so $S_{xy} = 8$. Also $S_{xx} = 4 + 1 + 0 + 1 + 4 = 10$ and $S_{yy} = 4 + 0 + 1 + 4 + 1 = 10$. So $r = \\dfrac{8}{\\sqrt{10 \\cdot 10}} = \\dfrac{8}{10} = 0.8$: strong positive correlation.","Least squares line $\\hat{y} = a + bx$: the slope is $b = \\dfrac{S_{xy}}{S_{xx}} = \\dfrac{8}{10} = 0.8$ and the intercept $a = \\bar{y} - b\\bar{x} = 3 - 0.8 \\cdot 3 = 0.6$. Prediction for $x = 6$: $\\hat{y} = 0.6 + 0.8 \\cdot 6 = 5.4$.","Two warnings. (1) $r = 0$ does not mean \"no relationship\": with $x = 1, \\dots, 5$ and $y = 4, 1, 0, 1, 4$ there is a perfect curved relationship, but $S_{xy} = 0$ and therefore $r = 0$. (2) Correlation is not causation: two variables moving together does not prove that one causes the other. Also, extrapolating (predicting far from the range of $x$) is risky."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"If $S_{xy} = -12$, $S_{xx} = 10$ and $S_{yy} = 14.4$, what is $r$?","opciones":["$-0.83$","$-1$","$1$","$-1.2$"],"respuesta":"$-1$","explicacion":"$r = \\dfrac{-12}{\\sqrt{10 \\cdot 14.4}} = \\dfrac{-12}{\\sqrt{144}} = \\dfrac{-12}{12} = -1$. The $-0.83$ comes from dividing by $14.4$ by mistake."},{"pregunta":"With the line $\\hat{y} = 2 + 3x$, what value does it predict for $x = 4$?","opciones":["$12$","$9$","$14$","$11$"],"respuesta":"$14$","explicacion":"$\\hat{y} = 2 + 3 \\cdot 4 = 14$."},{"pregunta":"Two variables have $r = 0.9$. Which statement is correct?","opciones":["One variable causes the other","There is no relationship between the variables","If x goes up by 1, y goes up by exactly 0.9","There is a strong positive linear relationship, but that does not prove that one causes the other"],"respuesta":"There is a strong positive linear relationship, but that does not prove that one causes the other","explicacion":"An r close to 1 indicates a strong positive linear relationship. Correlation describes how they move together, not why."}]$leccion_en$::jsonb,
      'visuales', $leccion_en$[{"tipo":"estadistica.dispersion","despuesDePaso":4,"titulo":"Strong positive correlation and its least squares line","x":[1,2,3,4,5],"y":[1,3,2,5,4],"etiquetaX":"x","etiquetaY":"y","mostrarRecta":true},{"tipo":"estadistica.dispersion","despuesDePaso":6,"titulo":"A perfect curved relationship with r = 0","x":[1,2,3,4,5],"y":[4,1,0,1,4],"etiquetaX":"x","etiquetaY":"y","mostrarRecta":true}]$leccion_en$::jsonb
    )
where slug = 'estadistica-clase-7-correlacion-y-regresion';

update public.techniques
set nombre_en = 'Class 8: Critical reading of charts',
    descripcion_en = 'How to read bars, lines, histograms and box plots, and how to spot charts that mislead through their scale.',
    contenido_en = contenido || jsonb_build_object(
      'pasos', $leccion_en$["A chart is a visual argument: before reading the data, read the title, the units and, above all, the axis. A chart can be well drawn and still mislead.","Bars: each bar is a category and its HEIGHT represents the value, which is why the axis must start at $0$. Histogram: touching bars for a continuous variable grouped into classes; each class is $[a, b)$ (it includes the lower limit, not the upper one) and the height is the frequency.","Lines: they are for series ordered in time. You read value by value and compare the slope between consecutive points: the steepest stretch is where it changed the most.","Box plot: the box goes from $Q_1$ to $Q_3$ (it contains the central 50 %), the inner line is the median, the whiskers reach the last data point that is not an outlier and the loose dots are outliers.","Outlier rule: a data point is an outlier if it is less than $Q_1 - 1.5\\,IQR$ or greater than $Q_3 + 1.5\\,IQR$. With $Q_1 = 40$ and $Q_3 = 60$: $IQR = 20$ and the fences are at $40 - 30 = 10$ and $60 + 30 = 90$. A data point at $95$ is an outlier; one at $85$ is not.","Misleading chart through scale. Two products sell $100$ and $104$ units: the real difference is $\\dfrac{104 - 100}{100} = 0.04$, that is 4 %. If the axis starts at $96$ instead of $0$, the bar of $100$ is $100 - 96 = 4$ units tall and the one of $104$ is $104 - 96 = 8$: it looks twice as tall, although it is only 4 % bigger.","How to protect yourself: (1) look at where the axis starts; (2) compute the real difference with the numbers, not with the height; (3) distrust cut axes, different scales between charts that are compared and icons that enlarge the area.","Training with bars. Sales per branch (axis from $0$ to $50$, with marks every $10$): North $30$, South $45$, East $20$ and West $35$. Value of a bar: follow its top end to the axis; the South one reaches $45$. Highest and lowest: the answer is the CATEGORY, not the number; the highest is South and the lowest is East. Difference: South minus East is $45 - 20 = 25$ units. Total: $30 + 45 + 20 + 35 = 130$.","Training with lines, part one: value, maximum and biggest increase. Visits per month from January to May: $10, 20, 25, 40, 45$. The value in March is $25$ and the maximum is reached in May. For the biggest increase, consecutive points are subtracted: $+10, +5, +15, +5$; the largest is $+15$, between March and April.","Training with lines, part two: the general trend. If each point is above the previous one, the series grows (the visits: $10 < 20 < 25 < 40 < 45$). If each point is below the previous one, it decreases. If it goes up and then down, it is described as \"goes up and then down\" ($20, 40, 50, 30, 10$). And if it varies by at most half a gridline (with marks every $10$, a total variation of $5$ or less), it stays almost constant: in $30, 32, 30, 33, 31$ the variation is $33 - 30 = 3$.","Training with histograms. Scores grouped into classes of $10$: $[0, 10)$ has $3$ data points, $[10, 20)$ has $8$, $[20, 30)$ has $12$, $[30, 40)$ has $7$ and $[40, 50)$ has $2$. Total data: the frequencies are added, $3 + 8 + 12 + 7 + 2 = 32$. Modal class: the one with the highest frequency, $[20, 30)$ with $12$ data points (the answer is the class, not the $12$). Data less than $30$: you add the classes to the left of the limit $30$, $3 + 8 + 12 = 23$, because each class includes its lower limit and not the upper one."]$leccion_en$::jsonb,
      'quiz', $leccion_en$[{"pregunta":"A bar chart has its vertical axis starting at 45 and two bars are worth 50 and 55. By what percentage is the second one really bigger than the first?","opciones":["100 %","5 %","10 %","50 %"],"respuesta":"10 %","explicacion":"The real difference is $\\dfrac{55 - 50}{50} = 0.1$, that is 10 %. Visually the bars measure $5$ and $10$ units (it looks $100$ % more), but it is an effect of the cut axis."},{"pregunta":"In a box plot, $Q_1 = 30$ and $Q_3 = 50$. From what value is a data point an outlier on the upper side?","opciones":["Greater than $60$","Greater than $70$","Greater than $80$","Greater than $100$"],"respuesta":"Greater than $80$","explicacion":"$IQR = 50 - 30 = 20$ and the upper fence is $50 + 1.5 \\cdot 20 = 80$."},{"pregunta":"In a histogram with classes $[10, 20)$, $[20, 30)$ and $[30, 40)$, which class does the data point $20$ belong to?","opciones":["To $[10, 20)$","To none","To both","To $[20, 30)$"],"respuesta":"To $[20, 30)$","explicacion":"Each class includes its lower limit and not the upper one: the $20$ goes in $[20, 30)$."},{"pregunta":"A histogram has the classes $[0, 10)$, $[10, 20)$ and $[20, 30)$ with frequencies $3, 8$ and $12$. How many data points are less than $20$?","opciones":["$8$","$11$","$12$","$23$"],"respuesta":"$11$","explicacion":"Only the classes to the left of the limit $20$ count: $3 + 8 = 11$. The $23$ is the total number of data points and the $12$ is the frequency of the class $[20, 30)$, which starts at $20$."},{"pregunta":"A line chart shows $20, 35, 30, 50$ and $45$ from January to May. In which stretch was the biggest increase?","opciones":["Between January and February","Between February and March","Between March and April","Between April and May"],"respuesta":"Between March and April","explicacion":"The differences between consecutive points are $+15, -5, +20, -5$: the biggest increase is $+20$, between March and April. Between February and March and between April and May the series goes down."}]$leccion_en$::jsonb,
